CREATE TABLE IF NOT EXISTS ducks_coffee_constructors_table (id BIGSERIAL PRIMARY KEY, "name" TEXT NOT NULL, price DECIMAL(15, 2) NULL, category_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, is_in_stock BOOLEAN DEFAULT TRUE NOT NULL, CONSTRAINT fk_ducks_coffee_constructors_table_category_id__id FOREIGN KEY (category_id) REFERENCES ducks_coffee_constructor_categories_table(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_ducks_coffee_constructors_table_shop_id__id FOREIGN KEY (shop_id) REFERENCES ducks_coffee_shop_table(id) ON DELETE CASCADE ON UPDATE RESTRICT)